// FilterPositionCollateralAdjusted retrieves and decodes "PositionCollateralAdjusted(bytes32,address,int256,uint256)" logs. Indexed filters follow ABI order.
func (c *IDiesisPerpsBookBinding) FilterPositionCollateralAdjusted(ctx context.Context, from, to *big.Int, indexed ...[]any) ([]IDiesisPerpsBookPositionCollateralAdjustedEvent, error) {
	if c.backend == nil {
		return nil, fmt.Errorf("IDiesisPerpsBookBinding has no backend")
	}
	definition, err := c.event("PositionCollateralAdjusted(bytes32,address,int256,uint256)")
	if err != nil {
		return nil, err
	}
	count := 0
	for _, arg := range definition.Inputs {
		if arg.Indexed {
			count++
		}
	}
	if len(indexed) > count {
		return nil, fmt.Errorf("too many indexed filters for %s", "PositionCollateralAdjusted(bytes32,address,int256,uint256)")
	}
	queries := indexed
	queries = append([][]any{{definition.ID}}, queries...)
	topics, err := abi.MakeTopics(queries...)
	if err != nil {
		return nil, err
	}
	logs, err := c.backend.FilterLogs(ctx, ethereum.FilterQuery{Addresses: []common.Address{c.address}, Topics: topics, FromBlock: from, ToBlock: to})
	if err != nil {
		return nil, err
	}
	out := make([]IDiesisPerpsBookPositionCollateralAdjustedEvent, 0, len(logs))
	for _, log := range logs {
		decoded, err := c.DecodePositionCollateralAdjustedEvent(log)
		if err != nil {
			return nil, err
		}
		out = append(out, decoded)
	}
	return out, nil
}

// WatchPositionCollateralAdjusted subscribes to new "PositionCollateralAdjusted(bytes32,address,int256,uint256)" logs and decodes them. Call Unsubscribe on the returned subscription when done.
func (c *IDiesisPerpsBookBinding) WatchPositionCollateralAdjusted(ctx context.Context, indexed ...[]any) (<-chan IDiesisPerpsBookPositionCollateralAdjustedEvent, event.Subscription, error) {
	if c.backend == nil {
		return nil, nil, fmt.Errorf("IDiesisPerpsBookBinding has no backend")
	}
	definition, err := c.event("PositionCollateralAdjusted(bytes32,address,int256,uint256)")
	if err != nil {
		return nil, nil, err
	}
	count := 0
	for _, arg := range definition.Inputs {
		if arg.Indexed {
			count++
		}
	}
	if len(indexed) > count {
		return nil, nil, fmt.Errorf("too many indexed filters for %s", "PositionCollateralAdjusted(bytes32,address,int256,uint256)")
	}
	queries := indexed
	queries = append([][]any{{definition.ID}}, queries...)
	topics, err := abi.MakeTopics(queries...)
	if err != nil {
		return nil, nil, err
	}
	logs := make(chan types.Log)
	upstream, err := c.backend.SubscribeFilterLogs(ctx, ethereum.FilterQuery{Addresses: []common.Address{c.address}, Topics: topics}, logs)
	if err != nil {
		return nil, nil, err
	}
	events := make(chan IDiesisPerpsBookPositionCollateralAdjustedEvent)
	subscription := event.NewSubscription(func(quit <-chan struct{}) error {
		defer upstream.Unsubscribe()
		defer close(events)
		for {
			select {
			case <-quit:
				return nil
			case <-ctx.Done():
				return ctx.Err()
			case err, ok := <-upstream.Err():
				if !ok {
					return nil
				}
				return err
			case log, ok := <-logs:
				if !ok {
					return nil
				}
				decoded, err := c.DecodePositionCollateralAdjustedEvent(log)
				if err != nil {
					return err
				}
				select {
				case events <- decoded:
				case <-quit:
					return nil
				case <-ctx.Done():
					return ctx.Err()
				}
			}
		}
	})
	return events, subscription, nil
}

// DecodeError identifies and decodes a declared custom error.
func (c *IDiesisPerpsBookBinding) DecodeError(raw []byte) (any, error) {
	if len(raw) < 4 {
		return nil, fmt.Errorf("revert payload is shorter than a selector")
	}
	return nil, fmt.Errorf("unknown custom error selector %x", raw[:4])
}
